mapper.select:
/* FAQ 목록 조회 */ SELECT F.FAQ_SN , F.FAQ_CLSF_CD , C.COM_CD_NM AS FAQ_CLSF_CD_NM , F.QSTN_TTL , F.ANS_CN FROM FAQ F LEFT JOIN COM_CD C ON C.COM_CD = F.FAQ_CLSF_CD AND C.COM_CD_PRNT_SN IS NOT NULL WHERE F.USE_YN = 'Y'
AND F.FAQ_CLSF_CD = #{faqClsfCd}
AND ( F.QSTN_TTL LIKE CONCAT('%', #{keyword}, '%') OR F.ANS_CN LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY F.SORT_SEQ ASC, F.FAQ_SN ASC

/* 관리자 FAQ 목록 조회 : 비노출 포함 */ SELECT F.FAQ_SN , F.FAQ_CLSF_CD , C.COM_CD_NM AS FAQ_CLSF_CD_NM , F.QSTN_TTL , F.SORT_SEQ , CASE WHEN F.USE_YN = 'Y' THEN TRUE ELSE FALSE END AS USE_YN , F.MDFCN_DT FROM FAQ F LEFT JOIN COM_CD C ON C.COM_CD = F.FAQ_CLSF_CD AND C.COM_CD_PRNT_SN IS NOT NULL
F.FAQ_CLSF_CD = #{faqClsfCd}
AND ( F.QSTN_TTL LIKE CONCAT('%', #{keyword}, '%') OR F.ANS_CN LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY F.SORT_SEQ ASC, F.FAQ_SN ASC

mapper.insert:
/* FAQ 등록 */
INSERT INTO FAQ
     ( FAQ_CLSF_CD
     , QSTN_TTL
     , ANS_CN
     , SORT_SEQ
     , USE_YN
     , REG_DT
     , MDFCN_DT
     , RGTR_ID
     , MDFR_ID )
VALUES
     ( #{faqClsfCd}
     , #{qstnTtl}
     , #{ansCn}
     , #{sortSeq}
     , #{useYn}
     , NOW()
     , NOW()
     , #{rgtrId}
     , #{mdfrId} )

mapper.update:
/* FAQ 수정 : null 인 값은 그대로 */
UPDATE FAQ
   SET MDFCN_DT = NOW()
     , MDFR_ID = #{mdfrId}

     , FAQ_CLSF_CD = #{faqClsfCd}


     , QSTN_TTL = #{qstnTtl}


     , ANS_CN = #{ansCn}


     , SORT_SEQ = #{sortSeq}


     , USE_YN = #{useYn}

 WHERE FAQ_SN = #{faqSn}
